   !> symmetric or LU)
   subroutine dpcm_original_assemble(state, r, n, k1, k2, xi, a, error, solver)
      !> State of dpcm_original
      type(dpcm_original_state), target, intent(inout) :: state
      !> Positions of the surface points
      real(wp), contiguous, intent(in) :: r(:, :)
      !> Outward unit normals at the surface points
