         tmp6 = tmp3 + tmp5
         tmp7 = -tmp6
         tmp8 = vn + tmp7
         tmp9 = dot(grad_vn, tmp8)
         energy = energy + tmp9
      end if

      state%ready = 3
   end subroutine dpcm_original_solve

