   !> DPCM, original form (gaussian charges): linear response of the v, vn gradient
   !>
   !> - Directions of v, vn only; the state is not changed
   !> - Needs dpcm_original_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_response(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original
      type(dpcm_original_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call dpcm_original_mf_response(state, dv, dvn, hvp_v, hvp_vn, error)
         return
      end if
      if (state%ready < 3) then
         call fatal_error(error, "[dpcm_original_response] call dpcm_original_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_original_response_one(state, dv(:, blk), dvn(:, blk), hvp_v(:, blk), &
                                         hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_original_response

   !> One direction of dpcm_original_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_response_one(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original
      type(dpcm_original_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[dpcm_original_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s3
      state%op1%c3 => state%s11
      tmp1 = 0.0_wp
      call state%solver%solve(state%op1, .false., dvn, tmp1, error)
      if (allocated(error)) return
      hvp_v = state%s13*tmp1
      tmp2 = 0.0_wp
      call state%solver%solve(state%op1, .true., dv, tmp2, error)
      if (allocated(error)) return
      hvp_vn = state%s13*tmp2
   end subroutine dpcm_original_response_one

   !> DPCM, original form (gaussian charges): energy derivatives with respect to the solvent
   !> parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs dpcm_original_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_param_weights(state, grad_eps, error)
      !> State of dpcm_original
      type(dpcm_original_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      real(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp4(:), tmp5(:)
      real(wp) :: tmp2, tmp3, tmp6, tmp7, tmp8, tmp9, tmp10

      if (state%matrix_free) then
         call dpcm_original_mf_param_weights(state, grad_eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 3) then
         call fatal_error(error, "[dpcm_original_param_weights] call dpcm_original_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_param_weights] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s3
      state%op1%c3 => state%s11
      tmp1 = 0.5_wp*state%v
      tmp2 = dot(tmp1, state%s12)
      tmp3 = (-0.5_wp)*state%s2
      tmp4 = tmp3*state%s14
      call gemv(state%s11, state%s12, tmp5, trans="t")
      tmp6 = dot(tmp4, tmp5)
      tmp7 = -tmp6
      tmp8 = tmp2 + tmp7
      tmp9 = state%s1**(-2)
      tmp10 = tmp8*tmp9
      grad_eps = 2.0_wp*tmp10
   end subroutine dpcm_original_param_weights

   !> DPCM, original form (gaussian charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs dpcm_original_assemble on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_complex_medium(state, eps, error)
      !> State of dpcm_original
      type(dpcm_original_complex_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      complex(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp) :: tmp1, tmp2

      if (state%matrix_free) then
         call dpcm_original_complex_mf_medium(state, eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[dpcm_original_complex_medium] call dpcm_original_assemble first")
         return
      end if
      state%cx_ready = 0
      if (allocated(state%cx_v)) deallocate (state%cx_v)
      if (allocated(state%cx_s12)) deallocate (state%cx_s12)
      if (allocated(state%cx_s14)) deallocate (state%cx_s14)
      if (allocated(state%cx_s16)) deallocate (state%cx_s16)
      if (allocated(state%cx_s17)) deallocate (state%cx_s17)
      if (allocated(state%cx_s18)) deallocate (state%cx_s18)
      if (allocated(state%cx_s19)) deallocate (state%cx_s19)
      if (allocated(state%cx_s21)) deallocate (state%cx_s21)
      if (allocated(state%cx_s22)) deallocate (state%cx_s22)
      if (allocated(state%cx_s23)) deallocate (state%cx_s23)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s12(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s14(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s16(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s17(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s18(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s19(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s21(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s22(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s23(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_complex_medium] allocation failed")
         return
      end if
      state%cx_s12 = 0.0_wp
      state%cx_s14 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op3%npt = npt
      state%op3%npoint = npt
      state%op3%id = 3
      state%op3%points => state%r
      state%op3%c1 => state%s3
      state%cx_s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%cx_s1
      tmp2 = (-2.0_wp)*tmp1
      state%cx_s2 = 1.0_wp + tmp2
      state%cx_s4 = -state%cx_s2
      state%op3%c2 = state%cx_s4
      state%op3%c3 => state%s11
      call state%solver%setup_complex(state%op3, error)
      if (allocated(error)) return
      state%cx_s13 = 0.5_wp*state%cx_s2

      state%cx_ready = 2
   end subroutine dpcm_original_complex_medium

   !> DPCM, original form (gaussian charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs dpcm_original_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] grad_vn  partial derivative of the energy with respect to vn
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_complex_solve(state, v, vn, energy, q, grad_v, grad_vn, error)
      !> State of dpcm_original
      type(dpcm_original_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Outward normal derivative of the solute potential at the surface points
      complex(wp), contiguous, intent(in) :: vn(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Partial derivative of the energy with respect to vn
      complex(wp), contiguous, intent(out) :: grad_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp5(:), tmp6(:)
      complex(wp), allocatable :: tmp2(:), tmp3(:), tmp4(:), tmp7(:), tmp8(:), tmp9(:), tmp10(:)
      complex(wp) :: tmp1, tmp11

      if (state%matrix_free) then
         call dpcm_original_complex_mf_solve(state, v, vn, energy, q, grad_v, grad_vn, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_complex_solve] call dpcm_original_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_solve] vn: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_solve] grad_v: wrong shape")
         return
      end if
      if (any(shape(grad_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_solve] grad_vn: wrong shape")
         return
      end if
      allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_complex_solve] allocation failed")
         return
      end if
      state%cx_ready = 2

      state%op3%points => state%r
      state%op3%c1 => state%s3
      state%op3%c3 => state%s11
      state%cx_v = v
      call state%solver%solve_complex(state%op3, .false., vn, state%cx_s12, error)
      if (allocated(error)) return
      call state%solver%solve_complex(state%op3, .true., state%cx_v, state%cx_s14, error)
      if (allocated(error)) return
      q = state%cx_s2*state%cx_s12
      tmp1 = sum(state%cx_v*q)
      energy = 0.5_wp*tmp1
      grad_v = state%cx_s13*state%cx_s12
      grad_vn = state%cx_s13*state%cx_s14
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp2 = state%s3*state%cx_s12
         tmp3 = 6.283185307179586_wp*tmp2
         call gemv(state%s11, real(state%cx_s12, wp), tmp5, trans="t")
         call gemv(state%s11, aimag(state%cx_s12), tmp6, trans="t")
         tmp4 = cmplx(tmp5, tmp6, wp)
         tmp7 = state%cx_s4*tmp4
         tmp8 = tmp3 + tmp7
         tmp9 = -tmp8
         tmp10 = vn + tmp9
         tmp11 = sum(grad_vn*tmp10)
         energy = energy + tmp11
      end if

      state%cx_ready = 3
   end subroutine dpcm_original_complex_solve

