   !> DPCM, original form (gaussian charges): linear response of the v, vn gradient
   !>
   !> - Directions of v, vn only; the state is not changed
   !> - Needs dpcm_original_complex_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_complex_response(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original
      type(dpcm_original_complex_state), intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      complex(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      complex(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call dpcm_original_complex_mf_response(state, dv, dvn, hvp_v, hvp_vn, error)
         return
      end if
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_complex_response] call dpcm_original_complex_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_original_complex_response_one(state, dv(:, blk), dvn(:, blk), hvp_v(:, blk), &
                                                 hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_original_complex_response

   !> One direction of dpcm_original_complex_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_complex_response_one(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original
      type(dpcm_original_complex_state), target, intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:)
      !> Direction for vn
      complex(wp), contiguous, intent(in) :: dvn(:)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      complex(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp), allocatable :: tmp1(:), tmp2(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_complex_response_one] allocation failed")
         return
      end if

      state%op3%points => state%r
      state%op3%c1 => state%s3
      state%op3%c3 => state%s11
      tmp1 = 0.0_wp
      call state%solver%solve_complex(state%op3, .false., dvn, tmp1, error)
      if (allocated(error)) return
      hvp_v = state%cx_s13*tmp1
      tmp2 = 0.0_wp
      call state%solver%solve_complex(state%op3, .true., dv, tmp2, error)
      if (allocated(error)) return
      hvp_vn = state%cx_s13*tmp2
   end subroutine dpcm_original_complex_response_one

   !> DPCM, original form (gaussian charges): energy derivatives with respect to the solvent
   !> parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs dpcm_original_complex_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_complex_param_weights(state, grad_eps, error)
      !> State of dpcm_original
      type(dpcm_original_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      complex(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp6(:), tmp7(:)
      complex(wp), allocatable :: tmp1(:), tmp4(:), tmp5(:)
      complex(wp) :: tmp2, tmp3, tmp8, tmp9, tmp10, tmp11, tmp12

      if (state%matrix_free) then
         call dpcm_original_complex_mf_param_weights(state, grad_eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_complex_param_weights] call dpcm_original_complex_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_complex_param_weights] allocation failed")
         return
      end if

      state%op3%points => state%r
      state%op3%c1 => state%s3
      state%op3%c3 => state%s11
      tmp1 = 0.5_wp*state%cx_v
      tmp2 = sum(tmp1*state%cx_s12)
      tmp3 = (-0.5_wp)*state%cx_s2
      tmp4 = tmp3*state%cx_s14
      call gemv(state%s11, real(state%cx_s12, wp), tmp6, trans="t")
      call gemv(state%s11, aimag(state%cx_s12), tmp7, trans="t")
      tmp5 = cmplx(tmp6, tmp7, wp)
      tmp8 = sum(tmp4*tmp5)
      tmp9 = -tmp8
      tmp10 = tmp2 + tmp9
      tmp11 = state%cx_s1**(-2)
      tmp12 = tmp10*tmp11
      grad_eps = 2.0_wp*tmp12
   end subroutine dpcm_original_complex_param_weights

   !> DPCM, original form (gaussian charges): build the cavity operators
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[in] r  positions of the surface points
   !> @param[in] n  outward unit normals at the surface points
   !> @param[in] k1  first principal curvature (positive where convex)
   !> @param[in] k2  second principal curvature (positive where convex)
   !> @param[in] xi  gaussian widths of the surface charges (ISWIG: xi_Born/(R_I sqrt(w_i)))
   !> @param[in] a  grid point areas
   !> @param[out] error  error handling; allocated on failure
   !> @param[in] solver  linear solver, copied into the state; default dense LAPACK (Cholesky,
   !> symmetric or LU)
   subroutine dpcm_original_mf_assemble(state, r, n, k1, k2, xi, a, error, solver)
      !> State of dpcm_original
      type(dpcm_original_state), target, intent(inout) :: state
      !> Positions of the surface points
      real(wp), contiguous, intent(in) :: r(:, :)
      !> Outward unit normals at the surface points
      real(wp), contiguous, intent(in) :: n(:, :)
      !> First principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k1(:)
      !> Second principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k2(:)
      !> Gaussian widths of the surface charges (ISWIG: xi_Born/(R_I sqrt(w_i)))
      real(wp), contiguous, intent(in) :: xi(:)
      !> Grid point areas
      real(wp), contiguous, intent(in) :: a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error
      !> Linear solver
      class(pcm_solver), intent(in), optional :: solver

      integer :: npt
      integer :: stat
      real(wp) :: tmp1
      integer :: i

      stat = 0
      npt = size(r, 2)
      if (npt < 1) then
         call fatal_error(error, "[dpcm_original_mf_assemble] empty discretization")
         return
      end if
      if (any(shape(r) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_mf_assemble] r: wrong shape")
         return
      end if
      if (any(shape(n) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_mf_assemble] n: wrong shape")
         return
      end if
      if (any(shape(k1) /= [npt])) then
         call fatal_error(error, "[dpcm_original_mf_assemble] k1: wrong shape")
         return
      end if
      if (any(shape(k2) /= [npt])) then
         call fatal_error(error, "[dpcm_original_mf_assemble] k2: wrong shape")
         return
      end if
      if (any(shape(xi) /= [npt])) then
         call fatal_error(error, "[dpcm_original_mf_assemble] xi: wrong shape")
         return
      end if
      if (any(shape(a) /= [npt])) then
         call fatal_error(error, "[dpcm_original_mf_assemble] a: wrong shape")
         return
      end if
      state%ready = 0
      if (allocated(state%solver)) deallocate (state%solver)
      if (allocated(state%v)) deallocate (state%v)
      if (allocated(state%a)) deallocate (state%a)
      if (allocated(state%s3)) deallocate (state%s3)
      if (allocated(state%xi)) deallocate (state%xi)
      if (allocated(state%r)) deallocate (state%r)
      if (allocated(state%n)) deallocate (state%n)
      if (allocated(state%k1)) deallocate (state%k1)
      if (allocated(state%k2)) deallocate (state%k2)
      if (allocated(state%s12)) deallocate (state%s12)
      if (allocated(state%s14)) deallocate (state%s14)
      if (allocated(state%s5)) deallocate (state%s5)
      if (allocated(state%s6)) deallocate (state%s6)
      if (allocated(state%s7)) deallocate (state%s7)
      if (allocated(state%s8)) deallocate (state%s8)
      if (allocated(state%s9)) deallocate (state%s9)
      if (allocated(state%s10)) deallocate (state%s10)
      if (allocated(state%s16)) deallocate (state%s16)
      if (allocated(state%s17)) deallocate (state%s17)
      if (allocated(state%s18)) deallocate (state%s18)
      if (allocated(state%s19)) deallocate (state%s19)
      if (allocated(state%s21)) deallocate (state%s21)
      if (allocated(state%s22)) deallocate (state%s22)
      if (allocated(state%s23)) deallocate (state%s23)
      if (allocated(state%s11)) deallocate (state%s11)
      state%npt = npt
      if (present(solver)) then
         allocate (state%solver, source=solver, stat=stat)
      else
         allocate (pcm_dense_solver :: state%solver, stat=stat)
      end if
      if (stat == 0) allocate (state%v(npt), stat=stat)
      if (stat == 0) allocate (state%a(npt), stat=stat)
      if (stat == 0) allocate (state%s3(npt), stat=stat)
      if (stat == 0) allocate (state%xi(npt), stat=stat)
      if (stat == 0) allocate (state%r(3, npt), stat=stat)
      if (stat == 0) allocate (state%n(3, npt), stat=stat)
      if (stat == 0) allocate (state%k1(npt), stat=stat)
      if (stat == 0) allocate (state%k2(npt), stat=stat)
      if (stat == 0) allocate (state%s12(npt), stat=stat)
      if (stat == 0) allocate (state%s14(npt), stat=stat)
      if (stat == 0) allocate (state%s5(npt), stat=stat)
      if (stat == 0) allocate (state%s6(npt), stat=stat)
      if (stat == 0) allocate (state%s7(npt), stat=stat)
      if (stat == 0) allocate (state%s8(npt), stat=stat)
      if (stat == 0) allocate (state%s9(npt), stat=stat)
      if (stat == 0) allocate (state%s10(npt), stat=stat)
      if (stat == 0) allocate (state%s16(npt), stat=stat)
      if (stat == 0) allocate (state%s17(npt), stat=stat)
      if (stat == 0) allocate (state%s18(npt), stat=stat)
      if (stat == 0) allocate (state%s19(npt), stat=stat)
      if (stat == 0) allocate (state%s21(npt), stat=stat)
      if (stat == 0) allocate (state%s22(npt), stat=stat)
      if (stat == 0) allocate (state%s23(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_mf_assemble] allocation failed")
         return
      end if
      state%s12 = 0.0_wp
      state%s14 = 0.0_wp
      call state%solver%reset(dpcm_original_n_operators)
      state%matrix_free = .true.

      state%a = a
      state%xi = xi
      state%r = r
      state%n = n
      state%k1 = k1
      state%k2 = k2
      do i = 1, npt
         tmp1 = 1.0_wp/state%a(i)
         state%s3(i) = tmp1
      end do
      state%s5 = state%r(1, :)
      state%s6 = state%r(2, :)
      state%s7 = state%r(3, :)
      state%s8 = state%n(1, :)
      state%s9 = state%n(2, :)
      state%s10 = state%n(3, :)

      state%ready = 1
      state%assembled = state%assembled + 1
   end subroutine dpcm_original_mf_assemble

   !> DPCM, original form (gaussian charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs dpcm_original_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_mf_medium(state, eps, error)
      !> State of dpcm_original
      type(dpcm_original_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp2

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[dpcm_original_mf_medium] call dpcm_original_assemble first")
         return
      end if
      state%ready = 1
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op2%npt = npt
      state%op2%npoint = npt
      state%op2%id = 2
      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%xi => state%xi
      state%op2%c1 => state%s3
      state%s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%s1
      tmp2 = (-2.0_wp)*tmp1
      state%s2 = 1.0_wp + tmp2
      state%s4 = -state%s2
      state%op2%c2 = state%s4
      call state%solver%setup(state%op2, error)
      if (allocated(error)) return
      state%s13 = 0.5_wp*state%s2

      state%ready = 2
   end subroutine dpcm_original_mf_medium

   !> DPCM, original form (gaussian charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs dpcm_original_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] grad_vn  partial derivative of the energy with respect to vn
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_mf_solve(state, v, vn, energy, q, grad_v, grad_vn, error)
      !> State of dpcm_original
      type(dpcm_original_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      real(wp), contiguous, intent(in) :: v(:)
      !> Outward normal derivative of the solute potential at the surface points
      real(wp), contiguous, intent(in) :: vn(:)
      !> Solvation energy
      real(wp), intent(out) :: energy
      !> Apparent surface charges
      real(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      real(wp), contiguous, intent(out) :: grad_v(:)
      !> Partial derivative of the energy with respect to vn
      real(wp), contiguous, intent(out) :: grad_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp9(:), tmp140(:), tmp141(:), &
                               tmp142(:), tmp143(:)
      real(wp) :: tmp1, tmp6, tmp7, tmp8, tmp144
      real(wp), allocatable :: tmp10(:)
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%ready < 2) then
         call fatal_error(error, "[dpcm_original_mf_solve] call dpcm_original_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_mf_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_mf_solve] vn: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[dpcm_original_mf_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_mf_solve] grad_v: wrong shape")
         return
      end if
      if (any(shape(grad_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_mf_solve] grad_vn: wrong shape")
         return
      end if
      allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp140(npt), stat=stat)
      if (stat == 0) allocate (tmp141(npt), stat=stat)
      if (stat == 0) allocate (tmp142(npt), stat=stat)
      if (stat == 0) allocate (tmp143(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_mf_solve] allocation failed")
         return
      end if
      state%ready = 2

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%xi => state%xi
      state%op2%c1 => state%s3
      state%v = v
      call state%solver%solve(state%op2, .false., vn, state%s12, error)
      if (allocated(error)) return
      call state%solver%solve(state%op2, .true., state%v, state%s14, error)
      if (allocated(error)) return
      q = state%s2*state%s12
      tmp1 = dot(state%v, q)
      energy = 0.5_wp*tmp1
      grad_v = state%s13*state%s12
      grad_vn = state%s13*state%s14
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp2 = state%s3*state%s12
         tmp3 = 6.283185307179586_wp*tmp2
         do i = 1, npt
            tmp6 = state%k1(i) + state%k2(i)
            tmp7 = tmp6*state%xi(i)
            tmp8 = (-0.19947114020071635_wp)*tmp7
            tmp5(i) = tmp8
         end do
         tmp9 = tmp5*state%s12
         tmp4 = tmp9
         block
            real(wp) :: tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp21, tmp22, &
                        tmp25, tmp29, tmp11, tmp20, tmp23, tmp24, tmp26, tmp27, tmp28, tmp30, &
                        tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, &
                        tmp41, tmp42, tmp43, tmp44, tmp45, tmp46, tmp47, tmp48, tmp49, tmp50, &
                        tmp51, tmp52, tmp53, tmp54, tmp55, tmp56, tmp57, tmp58, tmp59, tmp60, &
                        tmp61, tmp62, tmp63, tmp64, tmp65, tmp66, tmp67, tmp68, tmp69, tmp70, &
                        tmp71, tmp72, tmp73, tmp74, tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, &
                        tmp81, tmp82, tmp83, tmp84, tmp85, tmp86, tmp87, tmp88, tmp89, tmp90, &
                        tmp91, tmp92, tmp93, tmp94, tmp95, tmp96, tmp97, tmp98, tmp99, tmp100, &
                        tmp101, tmp102, tmp103, tmp104, tmp105, tmp106, tmp107, tmp108, tmp109, &
                        tmp110
            real(wp) :: tmp111, tmp112, tmp113, tmp114, tmp115, tmp116, tmp117, tmp118, tmp119, &
                        tmp120, tmp121, tmp122, tmp123, tmp124, tmp125, tmp126, tmp127, tmp128, &
                        tmp129, tmp130, tmp131, tmp132, tmp133, tmp134, tmp135, tmp136, tmp137, &
                        tmp138, tmp139

            !$omp parallel &
            !$omp& private(i, j, tmp10) &
            !$omp& shared(npt, state, tmp4) &
            !$omp& default(private)
            allocate (tmp10(npt))
            !$omp do schedule(static)
            do j = 1, npt
               tmp12 = state%s12(j)
               tmp13 = state%xi(j)
               tmp14 = state%s5(j)
               tmp15 = state%s6(j)
               tmp16 = state%s7(j)
               tmp17 = state%s8(j)
               tmp18 = state%s9(j)
               tmp19 = state%s10(j)
               tmp21 = tmp13**(2)
               tmp22 = -tmp14
               tmp25 = -tmp15
               tmp29 = -tmp16
               tmp11 = 0.0_wp
               !$omp simd &
               !$omp& private(tmp20, tmp23, tmp24, tmp26, tmp27, tmp28, tmp30, tmp31) &
               !$omp& private(tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39) &
               !$omp& private(tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46, tmp47) &
               !$omp& private(tmp48, tmp49) &
               !$omp& reduction(+: tmp11)
               do i = 1, j - 1
                  tmp23 = state%s5(i) + tmp22
                  tmp24 = tmp23**(2)
                  tmp26 = state%s6(i) + tmp25
                  tmp27 = tmp26**(2)
                  tmp28 = tmp24 + tmp27
                  tmp30 = state%s7(i) + tmp29
                  tmp31 = tmp30**(2)
                  tmp32 = tmp28 + tmp31
                  tmp33 = tmp21*tmp32
                  tmp34 = state%xi(i)**(2)
                  tmp35 = tmp33*tmp34
                  tmp36 = tmp34 + tmp21
                  tmp37 = (-81.0_wp)*tmp36
                  tmp38 = tmp35 + tmp37
                  tmp20 = 0.5_wp + sign(0.5_wp, tmp38)
                  tmp10(i) = tmp20
                  tmp39 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp38))
                  tmp40 = tmp32 + tmp39
                  tmp41 = 1.0_wp/sqrt(tmp40)
                  tmp42 = tmp41**(3)
                  tmp43 = tmp17*tmp23
                  tmp44 = tmp26*tmp18
                  tmp45 = tmp43 + tmp44
                  tmp46 = tmp30*tmp19
                  tmp47 = tmp45 + tmp46
                  tmp48 = tmp42*tmp47
                  tmp49 = tmp48*state%s12(i)
                  tmp11 = tmp11 + tmp49*tmp20
               end do
               !$omp simd &
               !$omp& private(tmp20, tmp23, tmp24, tmp26, tmp27, tmp28, tmp30, tmp31) &
               !$omp& private(tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39) &
               !$omp& private(tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46, tmp47) &
               !$omp& private(tmp48, tmp49) &
               !$omp& reduction(+: tmp11)
               do i = j + 1, npt
                  tmp23 = state%s5(i) + tmp22
                  tmp24 = tmp23**(2)
                  tmp26 = state%s6(i) + tmp25
                  tmp27 = tmp26**(2)
                  tmp28 = tmp24 + tmp27
                  tmp30 = state%s7(i) + tmp29
                  tmp31 = tmp30**(2)
                  tmp32 = tmp28 + tmp31
                  tmp33 = tmp21*tmp32
                  tmp34 = state%xi(i)**(2)
                  tmp35 = tmp33*tmp34
                  tmp36 = tmp34 + tmp21
                  tmp37 = (-81.0_wp)*tmp36
                  tmp38 = tmp35 + tmp37
                  tmp20 = 0.5_wp + sign(0.5_wp, tmp38)
                  tmp10(i) = tmp20
                  tmp39 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp38))
                  tmp40 = tmp32 + tmp39
                  tmp41 = 1.0_wp/sqrt(tmp40)
                  tmp42 = tmp41**(3)
                  tmp43 = tmp17*tmp23
                  tmp44 = tmp26*tmp18
                  tmp45 = tmp43 + tmp44
                  tmp46 = tmp30*tmp19
                  tmp47 = tmp45 + tmp46
                  tmp48 = tmp42*tmp47
                  tmp49 = tmp48*state%s12(i)
                  tmp11 = tmp11 + tmp49*tmp20
               end do
               do i = 1, npt
                  if (i == j) cycle
                  if (tmp10(i) < 0.5_wp) then
                     tmp50 = state%xi(i)**(2)
                     tmp51 = tmp50 + tmp21
                     tmp52 = 0.25_wp*tmp51
                     tmp53 = state%s5(i) + tmp22
                     tmp54 = tmp53**(2)
                     tmp55 = state%s6(i) + tmp25
                     tmp56 = tmp55**(2)
                     tmp57 = tmp54 + tmp56
                     tmp58 = state%s7(i) + tmp29
                     tmp59 = tmp58**(2)
                     tmp60 = tmp57 + tmp59
                     tmp61 = tmp21*tmp60
                     tmp62 = tmp61*tmp50
                     tmp63 = -tmp62
                     tmp64 = tmp52 + tmp63
                     if (tmp64 >= 0.0_wp) then
                        tmp66 = tmp17*tmp53
                        tmp67 = tmp55*tmp18
                        tmp68 = tmp66 + tmp67
                        tmp69 = tmp58*tmp19
                        tmp70 = tmp68 + tmp69
                        tmp71 = 1.0_wp/sqrt(tmp51)
