         return
      end if
      tmp1 = self%c1(idx)
      tmp2 = self%c3(idx, idx)
      tmp3 = 0.0_wp
      do i = 1, nb
         tmp3(i, i) = tmp1(i)
      end do
      tmp4 = 6.283185307179586_wp*tmp3
      tmp5 = transpose(tmp2)
      tmp6 = self%c2*tmp5
      a = tmp4 + tmp6
